def lexGreaterPermutation(s, target):
    n = len(s)
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1

    # Find the longest prefix of target we can match that still lets us
    # place a strictly larger letter at the next position
    best = -1
    for p in range(n):
        t = ord(target[p]) - 97
        # can we put a letter greater than target[p] at index p?
        for c in range(t + 1, 26):
            if cnt[c] > 0:
                best = p
                break
        # to continue the shared prefix we must be able to match target[p]
        if cnt[t] == 0:
            break
        cnt[t] -= 1

    if best == -1:
        return ""

    # Rebuild the answer: target[:best] + smallest greater letter + rest ascending
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1
    for ch in target[:best]:
        cnt[ord(ch) - 97] -= 1

    res = list(target[:best])
    for c in range(ord(target[best]) - 97 + 1, 26):
        if cnt[c] > 0:
            res.append(chr(c + 97))
            cnt[c] -= 1
            break
    for c in range(26):
        res.append(chr(c + 97) * cnt[c])
    return "".join(res)
